#!/usr/bin/env python3
"""
Deploy script — pushes index.html + scanner.py to GitHub.
Usage: python3 deploy.py <YOUR_GITHUB_PAT>
"""
import sys, json, base64
import urllib.request, urllib.error

if len(sys.argv) < 2:
    print("Usage: python3 deploy.py <GITHUB_PAT>")
    sys.exit(1)

TOKEN = sys.argv[1]
REPO  = "fovcuspro/sp500-swing-scanner"
API   = f"https://api.github.com/repos/{REPO}/contents"
HEADERS = {
    "Authorization": f"token {TOKEN}",
    "Accept": "application/vnd.github.v3+json",
    "Content-Type": "application/json",
    "User-Agent": "sp500-scanner-deploy"
}

def gh_get(path):
    req = urllib.request.Request(f"{API}/{path}", headers=HEADERS)
    with urllib.request.urlopen(req) as r:
        return json.loads(r.read())

def gh_put(path, content_b64, sha, message):
    body = json.dumps({"message": message, "content": content_b64, "sha": sha}).encode()
    req = urllib.request.Request(f"{API}/{path}", data=body, headers=HEADERS, method="PUT")
    with urllib.request.urlopen(req) as r:
        return json.loads(r.read())

files = {
    "index.html": {
        "content": "",
        "message": "feat: add Insights tab with AI strategy analysis"
    },
    "scanner.py": {
        "content": "",
        "message": "fix: tighten RSI filter to 40-52, add MIN_SCORE=6.0 threshold"
    }
}

for filename, info in files.items():
    print(f"\nPushing {filename}...")
    try:
        current = gh_get(filename)
        sha = current["sha"]
        result = gh_put(filename, info["content"], sha, info["message"])
        print(f"  ✓ {filename} pushed — commit {result['commit']['sha'][:7]}")
    except Exception as e:
        print(f"  ✗ {filename} failed: {e}")

print("\nDone. GitHub Pages will update in ~60 seconds.")
print("Scanner.py changes take effect on next GitHub Actions run (weekdays 17:00 UTC).")
